269	/** Real category breakdown for one family, for the per-family page's chips — a DB-wide groupBy, not just what's on the current page. */
270	export async function listCategoryCounts(family: string): Promise<{ category: string; count: number }[]> {
271	  const rows = await db.gameMod.groupBy({
272	    by: ["category"],
273	    where: { active: true, upstreamOk: true, gameFamily: family },
274	    _count: true,
275	  });
276	  return rows.map((r) => ({ category: r.category, count: r._count })).sort((a, b) => b.count - a.count);
277	}
