279	/** Real total downloads across a whole family (or the whole catalogue) — a DB aggregate, not a reduce over one loaded page. */
280	export async function totalDownloadsFor(family?: string): Promise<number> {
281	  const agg = await db.gameMod.aggregate({
282	    where: { active: true, upstreamOk: true, ...(family ? { gameFamily: family } : {}) },
283	    _sum: { downloads: true },
284	  });
285	  return agg._sum.downloads ?? 0;
286	}
