288	/** Every {family, slug} pair eligible for a public page — feeds generateStaticParams + sitemap.ts. */
289	export async function listCatalogSlugs(): Promise<{ family: string; slug: string }[]> {
290	  const rows = await db.gameMod.findMany({
291	    where: { active: true, upstreamOk: true },
292	    select: { gameFamily: true, slug: true },
293	  });
294	  return rows.map((r) => ({ family: r.gameFamily, slug: r.slug }));
295	}
