297	/** One mod's detail. Returns null for an unknown/inactive slug — callers should notFound(). */
298	export async function getCatalogMod(family: string, slug: string): Promise<ModDetail | null> {
299	  const row = await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: family, slug } } });
300	  if (!row || !row.active) return null;
301	  const aggs = await ratingAggs([row.id]);
302	  return toDetail(row, aggs.get(row.id));
303	}
304	
305	/** A handful of other mods in the same family, for "related mods" rails. */
306	export async function relatedCatalogMods(mod: ModDetail, take = 4): Promise<ModSummary[]> {
307	  const rows = await db.gameMod.findMany({
308	    where: { active: true, upstreamOk: true, gameFamily: mod.gameFamily, id: { not: mod.id } },
309	    orderBy: [{ downloads: "desc" }, { popularity: "desc" }],
310	    take: take * 3, // over-fetch a little so the same-category re-sort below has real options
311	  });
312	  const aggs = await ratingAggs(rows.map((r) => r.id));
313	  // Prefer same-category matches first, client-side sort (small result set).
314	  return rows
315	    .map((r) => toSummary(r, aggs.get(r.id)))
316	    .sort((a, b) => Number(b.category === mod.category) - Number(a.category === mod.category))
317	    .slice(0, take);
318	}
319	
320	/**
321	 * Real average rating + comment count for one mod, and its paginated,
322	 * genuinely user-authored comment list (ModRating rows with a non-null
323	 * `comment`). No fabricated numbers: a mod nobody has rated returns
324	 * avg: null, count: 0, comments: [].
325	 */
326	export async function getModRatingSummary(modId: string): Promise<{ avg: number | null; count: number }> {
327	  const agg = await db.modRating.aggregate({ where: { gameModId: modId }, _avg: { rating: true }, _count: { rating: true } });
328	  return { avg: agg._avg.rating, count: agg._count.rating };
329	}
330	
331	export async function listModComments(modId: string, opts: { take?: number; cursor?: string } = {}): Promise<{ comments: ModComment[]; nextCursor: string | null }> {
332	  const take = opts.take ?? 10;
333	  const rows = await db.modRating.findMany({
334	    where: { gameModId: modId, comment: { not: null } },
335	    orderBy: { createdAt: "desc" },
336	    take: take + 1,
337	    ...(opts.cursor ? { cursor: { id: opts.cursor }, skip: 1 } : {}),
338	    include: { user: { select: { id: true, name: true } } },
339	  });
340	  const page = rows.slice(0, take);
341	  const nextCursor = rows.length > take ? page[page.length - 1]!.id : null;
342	  return {
343	    comments: page.map((r) => ({
344	      id: r.id,
345	      rating: r.rating,
346	      comment: r.comment!,
347	      createdAt: r.createdAt.toISOString(),
348	      userId: r.userId,
349	      userName: r.user.name,
350	    })),
351	    nextCursor,
352	  };
353	}
