355	/** This viewer's own rating/comment on a mod, if they've left one — prefills the form as an edit rather than a fresh submit. */
356	export async function getMyModRating(modId: string, userId: string): Promise<{ rating: number; comment: string | null } | null> {
357	  const row = await db.modRating.findUnique({ where: { userId_gameModId: { userId, gameModId: modId } } });
358	  return row ? { rating: row.rating, comment: row.comment } : null;
359	}
