361	export type RecommendedPlan = { planName: string; ramMB: number; priceCents: number } | null;
362	
363	/**
364	 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
365	 * light-impact mods run on any active plan for the family; moderate needs at
366	 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
367	 * for the family that clears the bar, or null if none does (never guesses a
368	 * number that isn't a real, active, orderable plan).
369	 */
370	export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
371	  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
372	  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
373	  const pick = candidates[0];
374	  return pick ? { planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
375	}
376	
377	export function formatDownloads(n: number | null): string | null {
378	  if (n == null) return null;
379	  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
380	  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 10_000 ? 0 : 1)}K`;
381	  return String(n);
382	}
383	
384	export function formatBytes(bytes: number | null): string | null {
385	  if (!bytes || bytes <= 0) return null;
386	  if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(1)} GB`;
387	  if (bytes >= 1024 * 1024) return `${Math.round(bytes / (1024 * 1024))} MB`;
388	  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
389	}
