391	/**
392	 * The real, authoritative download for a mod detail page. Prefers the
393	 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
394	 * install it) so a visitor gets the actual file, not just a landing page;
395	 * falls back to the mod's own project/resource page (still the real,
396	 * authoritative source — never a Nxeon-hosted mirror) when the source can't
397	 * be resolved live or isn't one of the three we know how to resolve.
398	 */
399	export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<{ url: string; direct: boolean } | null> {
400	  const fallback = mod.url ? { url: mod.url, direct: false } : null;
401	  const id = mod.sourceId ?? "";
402	  if (!id) return fallback;
403	  const UA = "Nxeon/1.0 (nxlabs-catalog)";
404	  try {
405	    if (mod.source === "modrinth") {
406	      const headers: Record<string, string> = { "User-Agent": UA };
407	      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
408	      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(id)}/version`, { headers, next: { revalidate: 3600 } });
409	      if (!res.ok) return fallback;
410	      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
411	      const v = versions[0];
412	      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
413	      return file ? { url: file.url, direct: true } : fallback;
414	    }
415	    if (mod.source === "spigotmc") {
416	      // Spiget's own download endpoint 302s to the real jar — genuinely direct.
417	      return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
418	    }
419	    if (mod.source === "thunderstore") {
420	      const [namespace, ...rest] = id.split("-");
421	      if (!namespace || !rest.length) return fallback;
422	      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
423	        headers: { "User-Agent": UA },
424	        next: { revalidate: 3600 },
425	      });
426	      if (!res.ok) return fallback;
427	      const pkg = (await res.json()) as { latest?: { download_url?: string } };
428	      return pkg.latest?.download_url ? { url: pkg.latest.download_url, direct: true } : fallback;
429	    }
430	  } catch {
431	    return fallback;
432	  }
433	  return fallback;
434	}
