54	/* ── Live TPS sparkline — draws on view, pulsing playhead (from Cinematic) ── */
55	function TpsGraph({ accent, active, reduced }: { accent: string; active: boolean; reduced: boolean }) {
56	  const pts = [19.9, 20, 19.8, 20, 20, 19.7, 20, 19.9, 20, 20, 19.8, 20];
57	  const w = 220;
58	  const h = 46;
59	  const min = 19.5;
60	  const max = 20.2;
61	  const step = w / (pts.length - 1);
62	  const coords = pts.map((v, i) => {
63	    const x = i * step;
