437	/* ── Interactive pricing configurator ─────────────────────────────────────────
438	 * Drag the player count and the recommended plan + price update live. The
439	 * recommended RAM/vCPU/NVMe readout is GROUNDED in the real fitted player→resource
440	 * curve (lib/game-player-recommend — the same math the live GameDeployWizard uses),
441	 * and the plan match is driven by each plan's advertised slot capacity (falling
442	 * back to the RAM curve for VPS-style, slot-less plans). We reuse that recommend
443	 * logic rather than the DB-shaped <GameConfigurator/> because this preview runs on
444	 * PreviewGame data, not db.gamePlan rows — but the interaction language (player
445	 * control + brand-accented tiers) matches the site's GameConfigurator. */
446	function ramGbOf(ram: string) {
447	  return parseFloat(ram) || 0;
448	}
449	function gbLabel(mb: number) {
450	  const v = mb / 1024;
451	  return `${v.toFixed(v % 1 ? 1 : 0)} GB`;
452	}
