454	function PlanConfigurator({ game }: { game: PreviewGame }) {
455	  const reduced = usePrefersReducedMotion();
456	  const plans = game.plans;
457	
458	  const slotVals = plans.map((p) => p.slots).filter((s): s is number => s != null);
459	  const anySlots = slotVals.length > 0;
460	  const topSlots = anySlots ? Math.max(...slotVals) : null;
461	
462	  // Slider spans the plan ladder with ~30% headroom (to show "past our tiers"),
463	  // capped by the recommend module's own per-family ceiling.
464	  const sliderMax = topSlots
465	    ? Math.min(playerSliderMax(game.family), Math.max(topSlots + 16, Math.round(topSlots * 1.3)))
466	    : 64;
467	
468	  const popular = plans.find((p) => p.popular);
469	  const [players, setPlayers] = useState(popular?.slots ?? topSlots ?? Math.round(sliderMax / 2));
470	
471	  const spec = recommendedSpecForPlayers(game.family, players);
472	  const recRamGB = spec.ramMB / 1024;
473	
474	  const matchIdx = (() => {
475	    if (anySlots) {
476	      const i = plans.findIndex((p) => p.slots != null && p.slots >= players);
477	      return i === -1 ? plans.length - 1 : i;
478	    }
479	    const i = plans.findIndex((p) => ramGbOf(p.ram) >= recRamGB);
480	    return i === -1 ? plans.length - 1 : i;
481	  })();
482	  const matched = plans[matchIdx];
483	  const beyondTop = topSlots != null && players > topSlots;
484	
485	  const maxRamGB = Math.max(...plans.map((p) => ramGbOf(p.ram)), 1);
486	  const pct = (players / sliderMax) * 100;
487	
488	  return (
489	    <div className="relative overflow-hidden rounded-3xl border border-white/[0.07] bg-navy-900/50 p-6 backdrop-blur-md sm:p-8">
