499	            <IconUsers size={14} /> How many players?
500	          </p>
501	          <div className="mt-3 flex items-baseline gap-2">
502	            <span className="font-mono text-5xl font-bold tabular-nums text-white">{players}</span>
503	            <span className="text-sm text-slate-500">
504	              {beyondTop ? "players · past our tiers" : "concurrent players"}
505	            </span>
506	          </div>
507	
508	          {/* custom, brand-accented slider (inline-styled — no globals.css) */}
509	          <div className="relative mt-5 h-6">
510	            <div className="absolute inset-x-0 top-1/2 h-2 -translate-y-1/2 rounded-full bg-white/10" aria-hidden>
511	              <div
512	                className="h-full rounded-full"
513	                style={{ width: `${pct}%`, background: `linear-gradient(90deg, #3b82f6, ${game.accent})` }}
514	              />
