517	              className="pointer-events-none absolute top-1/2 h-5 w-5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 bg-white shadow-lg"
518	              style={{ left: `${pct}%`, borderColor: game.accent }}
519	              aria-hidden
