import { listCatalogFamilies } from "@/lib/mods-catalog";
import { db } from "@/lib/db";

async function main() {
  const families = await listCatalogFamilies();
  console.log("TOTAL FAMILIES:", families.length);
  console.log(families.map((f) => `${f.family}(${f.count})`).join(", "));

  const featuredCounts = await db.gameMod.groupBy({
    by: ["gameFamily"],
    where: { active: true, upstreamOk: true, featured: true },
    _count: true,
  });
  console.log("\nFEATURED COUNTS:", featuredCounts.map((f) => `${f.gameFamily}(${f._count})`).join(", "));

  const topOverall = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true },
    orderBy: [{ downloads: "desc" }],
    take: 5,
    select: { name: true, gameFamily: true, downloads: true },
  });
  console.log("\nTOP 5 OVERALL BY DOWNLOADS:", topOverall);

  const rustTop = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true, gameFamily: "rust" },
    orderBy: [{ downloads: "desc" }],
    take: 5,
    select: { name: true, downloads: true, featured: true },
  });
  console.log("\nRUST TOP 5:", rustTop);

  await db.$disconnect();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

