  LANDING_SLUGS,
  REGION_LANDING_SLUGS,
  type LandingPlan,
  type BuiltLanding,
} from "@/lib/marketing/locationLandings";
import {
  findGameLocationCombo,
  buildGameLocationLanding,
  buildGameLocationPreviewGame,
  findGeneralLocationCombo,
  buildGeneralLocationLanding,
  GAME_LOCATION_SLUGS,
  GENERAL_LOCATION_SLUGS,
  type GamePlanRow,
} from "@/lib/marketing/gameLocationLandings";

/**
 * Programmatic "(location) (service)" marketing landing pages, the region-tier
 * umbrella pages above them, AND (added here) the game-family × location
 * matrix + the general per-location VPS/Game-Server pages that don't already
 * exist via the tables above — see lib/marketing/gameLocationLandings.ts's
 * file doc for the full architecture note.
 *
 * Four data tables, one route: a slug is checked against the region matrix,
 * then the city matrix, then the game×location matrix, then the general
 * new-location matrix — in that order, so nothing here can ever shadow a
 * hand-written static marketing page (which wins at request time anyway) or
 * silently collide with an existing slug. Anything in none of the four falls
 * through to a 404. Real DB rows (VPS `Plan` or, for a game×location combo,
 * that family's real `GamePlan` rows) feed every page's pricing grid and
 * Product rich-result — nothing here is a hardcoded price.
 */

export const dynamic = "force-dynamic";

// Pre-declare every known slug across all four tables so Next can enumerate
// them at build time; unknown slugs are rejected in the page/metadata via
// notFound().
export function generateStaticParams(): Array<{ slug: string }> {
  return [...REGION_LANDING_SLUGS, ...LANDING_SLUGS, ...GAME_LOCATION_SLUGS, ...GENERAL_LOCATION_SLUGS].map((slug) => ({
    slug,
  }));
}

