/* ── Interactive pricing configurator ─────────────────────────────────────────
 * Drag the player count and the recommended plan + price update live. The
 * recommended RAM/vCPU/NVMe readout is GROUNDED in the real fitted player→resource
 * curve (lib/game-player-recommend — the same math the live GameDeployWizard uses),
 * and the plan match is driven by each plan's advertised slot capacity (falling
 * back to the RAM curve for VPS-style, slot-less plans). We reuse that recommend
 * logic rather than the DB-shaped <GameConfigurator/> because this preview runs on
 * PreviewGame data, not db.gamePlan rows — but the interaction language (player
 * control + brand-accented tiers) matches the site's GameConfigurator. */
function ramGbOf(ram: string) {
  return parseFloat(ram) || 0;
}
function gbLabel(mb: number) {
  const v = mb / 1024;
  return `${v.toFixed(v % 1 ? 1 : 0)} GB`;
}

function PlanConfigurator({ game }: { game: PreviewGame }) {
  const reduced = usePrefersReducedMotion();
  const plans = game.plans;

  const slotVals = plans.map((p) => p.slots).filter((s): s is number => s != null);
  const anySlots = slotVals.length > 0;
  const topSlots = anySlots ? Math.max(...slotVals) : null;

  // Slider spans the plan ladder with ~30% headroom (to show "past our tiers"),
  // capped by the recommend module's own per-family ceiling.
  const sliderMax = topSlots
    ? Math.min(playerSliderMax(game.family), Math.max(topSlots + 16, Math.round(topSlots * 1.3)))
    : 64;

  const popular = plans.find((p) => p.popular);
  const [players, setPlayers] = useState(popular?.slots ?? topSlots ?? Math.round(sliderMax / 2));

  const spec = recommendedSpecForPlayers(game.family, players);
  const recRamGB = spec.ramMB / 1024;

  const matchIdx = (() => {
    if (anySlots) {
      const i = plans.findIndex((p) => p.slots != null && p.slots >= players);
      return i === -1 ? plans.length - 1 : i;
    }
    const i = plans.findIndex((p) => ramGbOf(p.ram) >= recRamGB);
    return i === -1 ? plans.length - 1 : i;
  })();
  const matched = plans[matchIdx];
  const beyondTop = topSlots != null && players > topSlots;

  const maxRamGB = Math.max(...plans.map((p) => ramGbOf(p.ram)), 1);
  const pct = (players / sliderMax) * 100;

  return (
    <div className="relative overflow-hidden rounded-3xl border border-white/[0.07] bg-navy-900/50 p-6 backdrop-blur-md sm:p-8">
      <div
        className="pointer-events-none absolute -right-24 -top-24 h-56 w-56 rounded-full blur-3xl"
        style={{ background: `${game.accent}22` }}
        aria-hidden
      />
      <div className="relative grid gap-8 lg:grid-cols-2 lg:gap-12">
        {/* ── controls ─────────────────────────────────────────────────────── */}
        <div>
          <p className="flex items-center gap-2 text-[11px] font-semibold uppercase tracking-wide text-slate-400">
            <IconUsers size={14} /> How many players?
          </p>
          <div className="mt-3 flex items-baseline gap-2">
            <span className="font-mono text-5xl font-bold tabular-nums text-white">{players}</span>
            <span className="text-sm text-slate-500">
              {beyondTop ? "players · past our tiers" : "concurrent players"}
            </span>
          </div>

          {/* custom, brand-accented slider (inline-styled — no globals.css) */}
          <div className="relative mt-5 h-6">
            <div className="absolute inset-x-0 top-1/2 h-2 -translate-y-1/2 rounded-full bg-white/10" aria-hidden>
              <div
                className="h-full rounded-full"
                style={{ width: `${pct}%`, background: `linear-gradient(90deg, #3b82f6, ${game.accent})` }}
              />
            </div>
            <div
              className="pointer-events-none absolute top-1/2 h-5 w-5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 bg-white shadow-lg"
              style={{ left: `${pct}%`, borderColor: game.accent }}
              aria-hidden
            />
            <input
              type="range"
              min={1}
              max={sliderMax}
              value={players}
              onChange={(e) => setPlayers(Number(e.target.value))}
              aria-label="Concurrent players"
              aria-valuetext={`${players} players`}
              className="absolute inset-0 h-full w-full cursor-pointer opacity-0"
            />
          </div>
          <div className="mt-1.5 flex justify-between text-[11px] font-medium text-slate-500">
            <span>1</span>
            <span>{sliderMax}+</span>
          </div>

          {/* live recommended spec — grounded in the real resource curve */}
          <div className="mt-6">
            <p className="text-[11px] font-semibold uppercase tracking-wide text-slate-500">Recommended resources</p>
            <div className="mt-2.5 grid grid-cols-3 gap-2.5">
              {[
                { icon: <IconServer size={15} />, k: "RAM", v: gbLabel(spec.ramMB) },
                { icon: <IconGauge size={15} />, k: "vCPU", v: `${spec.cpuCores}` },
                { icon: <IconNvme size={15} />, k: "NVMe", v: `${spec.diskGB} GB` },
              ].map((s) => (
                <div key={s.k} className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
                  <span className="flex items-center gap-1.5 text-[10px] uppercase tracking-wide text-slate-500">
                    <span style={{ color: game.accent }}>{s.icon}</span> {s.k}
                  </span>
                  <span className="mt-0.5 block font-mono text-sm font-semibold tabular-nums text-white">{s.v}</span>
                </div>
              ))}
            </div>
            <p className="mt-2.5 text-[11px] leading-relaxed text-slate-500">
              Sized from the real {game.name} resource curve — a starting point you can resize any time.
            </p>
          </div>
        </div>

        {/* ── live plan chart ──────────────────────────────────────────────── */}
        <div>
          <p className="text-[11px] font-semibold uppercase tracking-wide text-slate-400">Your recommended plan</p>
          <div className="mt-3 space-y-2.5">
            {plans.map((p, i) => {
              const on = i === matchIdx;
              const w = Math.max(24, (ramGbOf(p.ram) / maxRamGB) * 100);
              return (
                <button
                  key={p.id}
                  type="button"
                  aria-pressed={on}
                  onClick={() =>
                    setPlayers(
                      p.slots ?? Math.min(sliderMax, Math.max(1, Math.round(((i + 1) / plans.length) * sliderMax))),
                    )
                  }
                  className={`group relative block w-full overflow-hidden rounded-xl border px-3.5 py-3 text-left ${
                    reduced ? "" : "transition-all duration-200"
                  } ${on ? "border-transparent" : "border-white/[0.07] hover:border-white/15"}`}
                  style={on ? { boxShadow: `0 0 0 1px ${game.accent}88, 0 16px 40px -20px ${game.accent}aa` } : undefined}
                >
                  <span
                    className={`pointer-events-none absolute inset-y-0 left-0 ${reduced ? "" : "transition-all duration-300"}`}
                    style={{
                      width: `${w}%`,
                      background: on
                        ? `linear-gradient(90deg, ${game.accent}55, ${game.accent}18)`
                        : "rgba(255,255,255,0.03)",
                    }}
                    aria-hidden
                  />
                  <span className="relative flex items-center justify-between gap-3">
                    <span className="min-w-0">
                      <span className="flex flex-wrap items-center gap-2">
                        <span className={`text-sm font-semibold ${on ? "text-white" : "text-slate-200"}`}>{p.tier}</span>
                        {on && (
                          <span
                            className="rounded-full px-2 py-0.5 text-[9px] font-bold uppercase tracking-wider text-white"
                            style={{ background: `linear-gradient(90deg, ${game.accent}, #3b82f6)` }}
                          >
                            Recommended
                          </span>
                        )}
                      </span>
                      <span className="mt-0.5 block text-[11px] text-slate-500">
                        {p.ram} RAM · {p.meta}
                      </span>
                    </span>
                    <span className="shrink-0 text-right">
                      <span className={`font-bold tabular-nums ${on ? "text-xl text-white" : "text-base text-slate-300"}`}>
                        {p.price}
                      </span>
                      <span className="text-[11px] text-slate-500">/mo</span>
                    </span>
                  </span>
                </button>
              );
            })}
          </div>

          {/* summary + CTA */}
          <div
            className="mt-5 rounded-2xl border p-4"
            style={{ borderColor: `${game.accent}44`, background: "rgba(255,255,255,0.02)" }}
          >
            {beyondTop ? (
              <p className="text-sm leading-relaxed text-slate-300">
                More than {topSlots} players? Get a{" "}
                <Link href="/contact" className="font-semibold" style={{ color: game.accent }}>
                  custom {game.name} server
                </Link>{" "}
                sized to your community.
              </p>
            ) : (
              <p className="text-sm leading-relaxed text-slate-300">
                For ~<span className="font-semibold text-white">{players}</span> players we recommend the{" "}
                <span className="font-semibold text-white">{matched.tier}</span> plan at{" "}
                <span className="font-semibold text-white">{matched.price}/mo</span>.
              </p>
            )}
            <Link
              href={deployHref({ service: "game", gameFamily: game.family, players, region: game.deployRegion })}
              className="btn-deploy mt-3.5 block px-4 py-3 text-center text-sm"
            >
              Deploy {matched.tier} — {matched.price}/mo
              <span className="dep-arrow" aria-hidden>→</span>
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ── plan card (from Cinematic) ───────────────────────────────────────────── */

