/**
 * Curated "Featured mods" rail — real `GameMod.featured` rows only (an
 * admin/import-time editorial flag, same field `ORDER_BY.featured` already
 * sorts by first), never a synthetic pick. Ordered by real downloads within
 * the featured set so the best-known featured mod leads. Returns fewer than
 * `take` (down to zero) when a family simply hasn't had any mods marked
 * featured yet — callers render nothing rather than pad with non-featured
 * rows, matching this file's no-guessing rule.
 */
export async function listFeaturedMods(family: string, take = 8): Promise<ModSummary[]> {
  const rows = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true, gameFamily: family, featured: true },
    orderBy: [{ downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
    take,
  });
  const aggs = await ratingAggs(rows.map((r) => r.id));
  return rows.map((r) => toSummary(r, aggs.get(r.id)));
}

/**
 * Curated "Most downloaded" rail — real `GameMod.downloads`, DB-side sorted
 * and DB-side filtered to `downloads: { not: null }`. That filter matters:
 * Postgres' default NULLS FIRST for a DESC sort would otherwise put every
 * never-verified (downloads: null) row ahead of real numbers — see the
 * `rust`/`cs2` families, which currently have zero mods with a real
 * `downloads` count and so correctly return an empty array here rather than
 * a page of nulls masquerading as "most downloaded". Omit `family` for a
 * cross-game rail (the NxLabs homepage's curated section).
 */
export async function listTopDownloadedMods(family?: string, take = 8): Promise<ModSummary[]> {
  const rows = await db.gameMod.findMany({
    where: { active: true, upstreamOk: true, downloads: { not: null }, ...(family ? { gameFamily: family } : {}) },
    orderBy: [{ downloads: "desc" }, { name: "asc" }],
    take,
  });
  const aggs = await ratingAggs(rows.map((r) => r.id));
  return rows.map((r) => toSummary(r, aggs.get(r.id)));
}

