 * homepage's featured/trending strips, mixing mods from every family).
 *
 * 2026-09-20: was a 24x24 square crop of the flat wordmark logo — the
 * owner's exact complaint reviewing a live screenshot was "so small you
 * can't even see it". Now renders the game's real portrait box art
 * (`GAME_ART_SLUG[family].poster`, the same asset GameCoverTile/the
 * game-servers carousel use — never a drawn/procedural stand-in) at a size
 * that's actually readable, with a border color genuinely sampled from that
 * same art file (see lib/game-poster-color.ts) rather than a hand-picked hex.
 * Falls back to the hero still, then the old square wordmark, for the
 * handful of "Wave 3 SCAFFOLD" families in GAME_ART_SLUG that don't have
 * real key-art yet.
 *
 * Async Server Component — fine to render directly inside ModCard, itself a
 * Server Component; both the color sample and the file-exists check are
 * cached (poster art) / already just a network-free disk read.
 *
 * NOT rendered on a single game's own dedicated page (app/**\/nxlabs/games/[family])
 * — there the game is already the page, so the badge would be redundant.
 */
export async function GameBadge({ family, className = "" }: { family: string; className?: string }) {
  const label = GAME_DISPLAY[family as GameFamily]?.name ?? family;
  const [art, accent] = await Promise.all([resolveBadgeArt(family), getPosterAccentColor(family)]);

  return (
    <span
      title={label}
      className={"absolute bottom-1.5 left-1.5 h-16 w-11 overflow-hidden rounded-md bg-navy-950/80 shadow-lg " + className}
      style={{ border: `2px solid ${accent}` }}
    >
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={art.src}
        alt={label}
        className={art.isPoster ? "h-full w-full object-cover" : "h-full w-full object-contain p-1"}
      />
    </span>
  );
}

