import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { StoreBrowser, type SortKey } from "@/components/mods/StoreBrowser";
import { ModCard } from "@/components/mods/ModCard";
import { PlanConfigurator } from "@/components/marketing/gamelanding/PlanConfigurator";
import { PREVIEW_GAMES, type PreviewGame } from "@/components/marketing/gamelanding/data";
import { GAME_ART_SLUG, GAME_DISPLAY, type GameFamily } from "@/lib/games";
import {
  listCatalogFamilies,
  listCategoryCounts,
  queryCatalogMods,
  listFeaturedMods,
  listTopDownloadedMods,
  totalDownloadsFor,
  formatDownloads,
} from "@/lib/mods-catalog";

export const dynamic = "force-dynamic";

const VALID_SORTS = new Set<SortKey>(["featured", "downloads", "latest", "rating"]);
function parseSort(v?: string): SortKey {
  return v && VALID_SORTS.has(v as SortKey) ? (v as SortKey) : "featured";
}

/**
 * A real per-game NxLabs landing page — item 7 of the NxLabs brief. Only
 * rendered for families that actually have catalogued mods (real
 * listCatalogFamilies() rows), never a placeholder page for a game with
 * nothing in it.
 */
export async function generateStaticParams(): Promise<Array<{ family: string }>> {
  const families = await listCatalogFamilies();
  return families.map((f) => ({ family: f.family }));
}

export async function generateMetadata({ params }: { params: Promise<{ family: string }> }): Promise<Metadata> {
  const { family } = await params;
  const label = GAME_DISPLAY[family as GameFamily]?.name ?? family;
  return {
    title: `${label} Mods & Plugins — NxLabs`,
    description: `Browse verified ${label} mods and plugins with real download counts, licenses, and version support — download free, or add straight to your Nxeon server.`,
    alternates: { canonical: `/mods/games/${family}` },
  };
}

type Search = { q?: string; sort?: string; category?: string; page?: string };

export default async function GameModsMarketingPage({
  params,
  searchParams,
}: {
  params: Promise<{ family: string }>;
  searchParams: Promise<Search>;
}) {
  const { family } = await params;
  const families = await listCatalogFamilies();
  const entry = families.find((f) => f.family === family);
  if (!entry) notFound();

  const sp = await searchParams;
  const q = (sp.q ?? "").trim();
  const sort = parseSort(sp.sort);
  const category = sp.category?.trim() || undefined;
  const page = Number(sp.page) || 1;

  const [categoryCounts, result, totalDownloads, featuredMods, topDownloaded] = await Promise.all([
    listCategoryCounts(family),
    queryCatalogMods({ family, category, q, sort, page }),
    totalDownloadsFor(family),
    listFeaturedMods(family),
    listTopDownloadedMods(family),
  ]);
  const { mods, total, totalPages, perPage, page: resolvedPage } = result;
  const label = GAME_DISPLAY[family as GameFamily]?.name ?? entry.label;
  const heroSlug = GAME_ART_SLUG[family as GameFamily]?.hero;

  // Real hosting plan/pricing data for this family — the SAME PREVIEW_GAMES
  // object every live /[game]-server-hosting page renders (see
  // rust-server-hosting/page.tsx: `const GAME = PREVIEW_GAMES.rust`), never a
  // second, independently-maintained copy of a price. `family` here is a
  // real GameMod.gameFamily value; 16 of the 17 real mod families today are
  // also PreviewGameKey values, but a mod-only family with no matching
  // Nxeon hosting plan (e.g. "schedule1" — see lib/games.ts: no dedicated
  // server exists for it, P2P/lobby only) genuinely has nothing to deploy,
  // so the section below (and the hosting-plans link in the hero) are
  // honestly omitted rather than pointing at a plan that doesn't exist.
  const previewGame: PreviewGame | undefined = (PREVIEW_GAMES as Record<string, PreviewGame>)[family];

  // Real, DB-wide category counts (listCategoryCounts' own groupBy) — not
  // derived from `mods`, which is only the current page.
  const chips = categoryCounts.map((c) => ({ key: c.category, label: c.category, count: c.count }));

  return (
    <>
      <section className="relative overflow-hidden">
        {heroSlug && (
          <div className="absolute inset-0 -z-10">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={`/games/art/${heroSlug}_hero.jpg`} alt="" className="h-full w-full object-cover opacity-30" />
            {/* var(--color-bg), not var(--bg) — the latter is never defined in
                globals.css (only --color-bg is), so this gradient stop used to
                be silently invalid CSS and rendered nothing at all: the raw
                image showed through completely unblended, so whichever part of
                the source art happened to be bright/colorful (the game's own
                logo lockup, usually off-center) read as a stark "boxed" patch
                against the plain dark backdrop everywhere else, while the copy
                sat in what looked like a bare column beside it. Same fix and
                same three-stop shape as the mod detail pages' identical hero
                overlay (app/(marketing)/mods/[family]/[slug]/page.tsx), which
                already called this file out as carrying the same latent bug. */}
            <div className="absolute inset-0 bg-gradient-to-t from-[var(--color-bg)] via-[var(--color-bg)]/80 to-[var(--color-bg)]/40" />
          </div>
        )}
        <div className="rail py-20 sm:py-28">
          <p className="text-xs font-semibold uppercase tracking-widest text-brand-300">
            <Link href="/mods" className="hover:underline">
              NxLabs
            </Link>{" "}
            / {label}
          </p>
          <h1 className="mt-3 text-4xl font-bold tracking-tight text-[var(--fg)] sm:text-5xl">{label} mods &amp; plugins</h1>
          <p className="mt-4 max-w-2xl text-lg text-[var(--fg-muted)]">
            {entry.count} verified add-ons for {label} — real download counts, real licenses, and a direct link to the
            source. Free for anyone, one click if you have a matching Nxeon server.
          </p>
          <div className="mt-6 flex flex-wrap gap-6 text-sm text-[var(--fg-muted)]">
            <span>
              <strong className="text-[var(--fg)]">{entry.count}</strong> mods &amp; plugins
            </span>
            {totalDownloads > 0 && (
              <span>
                <strong className="text-[var(--fg)]">{formatDownloads(totalDownloads)}</strong> total downloads
              </span>
            )}
          </div>
          <div className="mt-6 flex gap-3">
            <a href="#browse" className="btn-primary">
              Browse {label} mods
            </a>
            {previewGame && (
              <Link href={`/${family}-server-hosting`} className="btn-secondary">
                See {label} hosting plans
              </Link>
            )}
          </div>
        </div>
      </section>

      {/* Real "deploy this server" section — the exact same interactive
          configurator and PREVIEW_GAMES plan/price data as the live
          /[game]-server-hosting page (components/marketing/gamelanding/
          PlanConfigurator.tsx, extracted out of GameLandingCombined.tsx so
          there is only ever one implementation of this widget — never a
          second copy of a game's pricing that could drift). Omitted
          entirely for a family with no real Nxeon hosting plan, see the
          `previewGame` comment above. */}
      {previewGame && (
        <Section tone="panel">
          <div id="deploy">
            <SectionTitle
              eyebrow="Deploy this server"
              title={`Get a real ${label} server for these mods`}
              sub={`Same plans, same prices as ${label} server hosting — drag your player count and deploy straight from here.`}
            />
            <div className="mx-auto mt-10 max-w-5xl">
              <PlanConfigurator game={previewGame} />
            </div>
          </div>
        </Section>
      )}

      {featuredMods.length > 0 && (
        <Section>
          <div id="featured">
            <SectionTitle eyebrow="Editor's picks" title={`Featured ${label} mods`} />
            <div className="mt-6 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
              {featuredMods.map((mod) => (
                <ModCard key={mod.id} mod={mod} href={`/mods/${mod.gameFamily}/${mod.slug}`} />
              ))}
            </div>
          </div>
        </Section>
      )}

      {topDownloaded.length > 0 && (
        <Section>
          <div id="top-downloaded">
            <SectionTitle
              eyebrow="Real downloads, real ranking"
              title={`Most downloaded ${label} mods`}
              sub="Ranked by real download counts pulled from each mod's own source."
            />
            <div className="mt-6 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
              {topDownloaded.map((mod) => (
                <ModCard key={mod.id} mod={mod} href={`/mods/${mod.gameFamily}/${mod.slug}`} />
              ))}
            </div>
          </div>
        </Section>
      )}

      <Section>
        <div id="browse">
          <StoreBrowser
            mods={mods}
            total={total}
            page={resolvedPage}
            totalPages={totalPages}
            perPage={perPage}
            chips={chips}
            chipField="category"
            activeChipKey={category}
            basePath="/mods"
            browsePath={`/mods/games/${family}`}
            q={q}
            sort={sort}
            searchPlaceholder={`Search ${label} mods…`}
          />
        </div>
      </Section>
    </>
  );
}

